  document.querySelectorAll('.svc-card').forEach(c=>{
    c.onclick = ()=> c.classList.toggle('open');
  });

  document.getElementById('hajjList').innerHTML = HAJJ_POINTS[lang].map(p=>`<div>${p}</div>`).join('');

  const umrahGrid = document.getElementById('umrahGrid');
  umrahGrid.innerHTML = SERVICES[1][lang].items.map(it=>`<div class="why-card" style="padding:20px;"><div class="ic" style="font-size:16px;">🌙</div><h4 style="font-size:13.5px;">${it}</h4></div>`).join('');

